const lessons=[{"sentences":[{"speaker":"A","text":"We need to select a suitable demonstration room for the upcoming client presentation next Tuesday.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.139},{"speaker":"B","text":"I checked the schedule and only the small conference suite on the third floor is available.","position":2,"audioStartSeconds":6.339,"audioEndSeconds":11.6275},{"speaker":"A","text":"That room might be too cramped because we are expecting twelve people to attend the session.","position":3,"audioStartSeconds":11.8275,"audioEndSeconds":17.369541666666667},{"speaker":"B","text":"We could easily move the workshop to the main auditorium if they approve the request.","position":4,"audioStartSeconds":17.569541666666666,"audioEndSeconds":22.712083333333332},{"speaker":"A","text":"The auditorium is already booked for a morning seminar by the marketing team.","position":5,"audioStartSeconds":22.91208333333333,"audioEndSeconds":27.860541666666666},{"speaker":"B","text":"Let us ask management to swap our booking since our presentation is much more critical.","position":6,"audioStartSeconds":28.060541666666666,"audioEndSeconds":33.524458333333335},{"speaker":"A","text":"That sounds like a risky plan which might cause unnecessary conflicts with colleagues.","position":7,"audioStartSeconds":33.72445833333333,"audioEndSeconds":39.25279166666667},{"speaker":"B","text":"I will call the facilities manager right now to see if another medium room was recently cancelled.","position":8,"audioStartSeconds":39.45279166666667,"audioEndSeconds":45.45791666666667},{"speaker":"A","text":"Good morning because I am calling to arrange the delivery of the product samples we ordered last week.","role":"section-start","position":9,"audioStartSeconds":50.45791666666667,"audioEndSeconds":56.35995833333333},{"speaker":"B","text":"Our logistics department received your shipment yesterday afternoon at the central warehouse.","position":10,"audioStartSeconds":56.559958333333334,"audioEndSeconds":62.30741666666667},{"speaker":"A","text":"Could you deliver those heavy boxes directly to our office on the fourth floor instead?","position":11,"audioStartSeconds":62.507416666666664,"audioEndSeconds":67.64920833333333},{"speaker":"B","text":"The delivery driver usually drops everything off downstairs unless you pay an extra fee.","position":12,"audioStartSeconds":67.84920833333334,"audioEndSeconds":73.53216666666667},{"speaker":"A","text":"We can definitely cover the additional cost if your team brings them up before noon.","position":13,"audioStartSeconds":73.73216666666667,"audioEndSeconds":78.97241666666666},{"speaker":"B","text":"I will inform the driver immediately so they arrive at your desk by eleven o clock.","position":14,"audioStartSeconds":79.17241666666666,"audioEndSeconds":84.43316666666666}],"questions":[{"prompt":"What event are the first two speakers discussing?","options":["A client presentation.","A marketing seminar.","A facilities meeting."],"answer":"A","evidenceSentence":1,"evidence":"We need to select a suitable demonstration room for the upcoming client presentation next Tuesday.","explanation":"Người nói nhắc đến buổi thuyết trình cho khách hàng vào thứ Ba tới."},{"prompt":"Why is the third floor conference suite considered unsuitable?","options":["It is too expensive.","It is too small.","It is already booked."],"answer":"B","evidenceSentence":3,"evidence":"That room might be too cramped because we are expecting twelve people to attend the session.","explanation":"Phòng này quá chật chội cho mười hai người tham dự."},{"prompt":"What solution does the second speaker initially suggest?","options":["Swapping rooms with marketing.","Moving to the main auditorium.","Asking management for help."],"answer":"B","evidenceSentence":4,"evidence":"We could easily move the workshop to the main auditorium if they approve the request.","explanation":"Người thứ hai đề xuất chuyển sang phòng hội trường chính."},{"prompt":"What is the purpose of the second conversation?","options":["To complain about a delay.","To arrange a sample delivery.","To order new products."],"answer":"B","evidenceSentence":9,"evidence":"Good morning because I am calling to arrange the delivery of the product samples we ordered last week.","explanation":"Cuộc gọi nhằm sắp xếp việc giao hàng mẫu sản phẩm."},{"prompt":"Where are the product samples currently located?","options":["At the central warehouse.","On the fourth floor.","At the front desk."],"answer":"A","evidenceSentence":10,"evidence":"Our logistics department received your shipment yesterday afternoon at the central warehouse.","explanation":"Lô hàng đang ở kho trung tâm."},{"prompt":"What condition must be met for the delivery driver to bring the boxes upstairs?","options":["A manager must approve it.","An extra fee must be paid.","The driver must arrive before noon."],"answer":"B","evidenceSentence":12,"evidence":"The delivery driver usually drops everything off downstairs unless you pay an extra fee.","explanation":"Phải trả thêm phí để tài xế mang đồ lên lầu."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
